package com.agriconnect.service; import com.agriconnect.model.AppUser; import com.agriconnect.repository.UserRepository; import org.springframework.stereotype.Service; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; @Service public class AuthService {private final UserRepository r; private final BCryptPasswordEncoder e=new BCryptPasswordEncoder(); public AuthService(UserRepository r){this.r=r;} public AppUser register(AppUser u){if(r.existsByEmail(u.getEmail()))throw new IllegalArgumentException("Email already registered");u.setPassword(e.encode(u.getPassword()));return r.save(u);} public AppUser login(String email,String pass){AppUser u=r.findByEmail(email).orElse(null);return u!=null&&e.matches(pass,u.getPassword())?u:null;}}